contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    receive() external payable {}

    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(address(this).balance >= amount);

        c.sendMoney(address(this), amount, ""); if (__ESBMC_reverted()) return;

        uint balanceBefore = address(c).balance;
        uint callerBefore = address(this).balance;

        bool reverted;
        c.withdraw(amount); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint balanceAfter = address(c).balance;
        uint callerAfter = address(this).balance;

        assert(
            (reverted == (amount > balanceBefore)) &&
            (!reverted ? (callerAfter == callerBefore + amount && balanceAfter == balanceBefore - amount) : (callerAfter == callerBefore && balanceAfter == balanceBefore))
        );
    }
}

