pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleWallet c;

    function setUp() public {
        c = new SimpleWallet();
    }

    function _run(uint256 amount) internal {
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= amount);
        try c.sendMoney(address(this), amount, "") {} catch { return; }
        uint balanceBefore = address(c).balance;
        uint callerBefore = address(this).balance;
        bool reverted;
        try c.withdraw(amount) {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint balanceAfter = address(c).balance;
        uint callerAfter = address(this).balance;
        assertTrue((reverted == (amount > balanceBefore)) &&
            (!reverted ? (callerAfter == callerBefore + amount && balanceAfter == balanceBefore - amount) : (callerAfter == callerBefore && balanceAfter == balanceBefore)));
    }

    function testFuzz_run(uint256 amount) public {
        _run(amount);
    }

    receive() external payable {}
}
